class Shuffler {
  private original: number[];
  constructor(nums: number[]) { this.original = [...nums]; }

  reset(): number[] { return [...this.original]; }

  shuffle(): number[] {
    const a = [...this.original];
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1)); // 0..i inclusive
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }
}

